def _fresh_economy_db(tmp_path, monkeypatch):
    import utils.bot_db as bot_db
    import utils.economy_db as economy_db
    # Point the migration source at a non-existent temp file so the legacy
    # bot.db economy data is never pulled into the temp economy.db during tests.
    monkeypatch.setattr(bot_db, "DB_DIR", str(tmp_path))
    monkeypatch.setattr(bot_db, "DB_PATH", str(tmp_path / "bot.db"))
    monkeypatch.setattr(bot_db, "_DB_READY", False)
    monkeypatch.setattr(bot_db, "_MIGRATION_ATTEMPTED", False)
    monkeypatch.setattr(economy_db, "DB_DIR", str(tmp_path))
    monkeypatch.setattr(economy_db, "DB_PATH", str(tmp_path / "economy.db"))
    monkeypatch.setattr(economy_db, "_DB_READY", False)
    monkeypatch.setattr(economy_db, "_BOT_DB_MIGRATED", False)
    return economy_db


def test_removed_default_item_is_not_reseeded(tmp_path, monkeypatch):
    """Deleting a default shop item must stay deleted even after re-seeding (on .shop / restart)."""
    economy_db = _fresh_economy_db(tmp_path, monkeypatch)
    guild_id = 999
    name = "🎆 Fireworks"

    economy_db.add_shop_item(guild_id, name=name, description="Reveal", price=100, is_default=True)
    assert economy_db.remove_shop_item_by_name(guild_id, name) is True
    assert economy_db.get_shop_items(guild_id) == []

    cog = economy_cog.Economy(bot=MagicMock())
    guild = SimpleNamespace(id=guild_id)
    asyncio.run(cog._ensure_default_items(guild))
    asyncio.run(cog._ensure_default_items(guild))

    names = [item["name"] for item in economy_db.get_shop_items(guild_id)]
    assert name not in names


def test_removed_default_item_stays_gone_across_restart(tmp_path, monkeypatch):
    """Simulate bot restart: fresh DB connection/state must not resurrect the item."""
    economy_db = _fresh_economy_db(tmp_path, monkeypatch)
    guild_id = 777
    name = "👟 Shoes"

    economy_db.add_shop_item(guild_id, name=name, description="Extra visit", price=250, is_default=True)
    assert economy_db.remove_shop_item_by_name(guild_id, name) is True

    # Simulate restart: reset in-memory ready flags, reconnect to same file.
    monkeypatch.setattr(economy_db, "_DB_READY", False)
    monkeypatch.setattr(economy_db, "_BOT_DB_MIGRATED", False)

    cog = economy_cog.Economy(bot=MagicMock())
    asyncio.run(cog._ensure_default_items(SimpleNamespace(id=guild_id)))

    names = [item["name"] for item in economy_db.get_shop_items(guild_id)]
    assert name not in names


