def test_readded_deleted_default_appears_via_additem_flow(tmp_path, monkeypatch):
    """Manually re-adding a deleted default (.additem flow) shows it in the shop and seeding does not duplicate it."""
    economy_db = _fresh_economy_db(tmp_path, monkeypatch)
    guild_id = 333
    name = "🎆 Fireworks"

    economy_db.add_shop_item(guild_id, name=name, description="Reveal", price=100, is_default=True)
    assert economy_db.remove_shop_item_by_name(guild_id, name) is True
    assert economy_db.get_shop_items(guild_id) == []

    # Same as .additem: custom (non-default) insert of the same name.
    economy_db.add_shop_item(guild_id, name=name, description="", price=120, is_default=False)

    cog = economy_cog.Economy(bot=MagicMock())
    asyncio.run(cog._ensure_default_items(SimpleNamespace(id=guild_id)))
    asyncio.run(cog._ensure_default_items(SimpleNamespace(id=guild_id)))

    items = economy_db.get_shop_items(guild_id)
    matching = [it for it in items if it["name"] == name]
    assert len(matching) == 1
    assert matching[0]["price"] == 120
    assert matching[0]["is_default"] is False


