class _Perms:
    def __init__(self, send=True, read=True, administrator=False):
        self.send_messages = send
        self.read_messages = read
        self.administrator = administrator


class _User:
    def __init__(self, uid, name, roles=None, guild_permissions=None, bot=False):
        self.id = uid
        self.display_name = name
        self.name = name
        self.mention = f"<@{uid}>"
        self.roles = roles or []
        self.guild_permissions = guild_permissions or _Perms()
        self.bot = bot

    def __eq__(self, other):
        if isinstance(other, _User):
            return self.id == other.id
        return NotImplemented


class _Role:
    def __init__(self, name):
        self.name = name
        self.mention = f"<@&role:{name}>"


_CATEGORY_IDS = iter(range(1, 10_000))


class _Channel:
    def __init__(self, cid, name, category=None, members=None):
        self.id = cid
        self.name = name
        self.category = category
        self.members = members or []
        self.mention = f"<#{cid}>"

    @property
    def category_id(self):
        return self.category.id if self.category else None

    def permissions_for(self, member):
        return _Perms(send=member in self.members, read=member in self.members)


class _Category:
    def __init__(self, name, channels=None):
        self.id = next(_CATEGORY_IDS)
        self.name = name
        self.text_channels = channels or []


class _Guild:
    def __init__(self, gid):
        self.id = gid
        self.categories = []
        self.channels = []
        self.roles = []
        self.members = []
        self.text_channels = []

    def cat(self, name):
        c = _Category(name)
        self.categories.append(c)
        return c

    def role(self, name):
        r = _Role(name)
        self.roles.append(r)
        return r

    def ch(self, cid, name, category=None, members=None):
        c = _Channel(cid, name, category=category, members=members)
        self.channels.append(c)
        if category is not None:
            category.text_channels.append(c)
        else:
            self.text_channels.append(c)
        return c

    def get_member(self, member_id):
        return next((m for m in self.members if m.id == member_id), None)

    def get_channel(self, cid):
        return next((c for c in self.channels if c.id == cid), None)


def _setup_guild_data(gid):
    save_guild_data(gid, {
        "rc_category_name": "ROLES",
        "alt_category_name": "ALT",
        "dead_rc_category_name": "DEAD",
        "houses_category_name": "HOUSES",
        "alive_role_name": "Alive",
        "sponsor_role_name": "Sponsor",
        "overseer_role_name": "Overseer",
        "whisper_logs_channel_name": "whisper-logs",
        "showwhispersender": False,
        "economy_collect_amount": 100,
        "peep_holes": {},
    })


def _make_ctx(guild, author, channel):
    ctx = SimpleNamespace()
    ctx.guild = guild
    ctx.author = author
    ctx.channel = channel
    ctx.bot = SimpleNamespace()
    ctx.sent = []
    ctx.embeds = []

    async def _send(content=None, embed=None, view=None, ephemeral=False):
        ctx.sent.append(content if content else (embed.title if embed else ""))
        if embed is not None:
            ctx.embeds.append(embed)
        return MagicMock()

    ctx.send = _send
    return ctx


def _make_interaction(guild, user, channel, client=None):
    i = SimpleNamespace()
    i.user = user
    i.guild = guild
    i.guild_id = guild.id
    i.channel = channel
    i.channel_id = channel.id
    i.client = client
    i.response = SimpleNamespace(sent=[], deferred=False)

    async def _send_message(content=None, embed=None, view=None, ephemeral=False):
        i.response.sent.append(content if content else (embed.title if embed else ""))
        return MagicMock()

    async def _defer(*args, **kwargs):
        i.response.deferred = True

    i.response.send_message = _send_message
    i.response.defer = _defer
    i.followup = SimpleNamespace(sent=[])

    async def _followup_send(content=None, embed=None, view=None, ephemeral=False):
        i.followup.sent.append(content if content else (embed.title if embed else ""))
        return MagicMock()

    i.followup.send = _followup_send
    i.original_response = AsyncMock(return_value=MagicMock(id=1))
    return i


# --- Fix 1: duplicate / empty-name add_shop_item --------------------------- #

def test_add_shop_item_duplicate_returns_existing_id(tmp_path, monkeypatch):
    economy_db = _fresh_economy_db(tmp_path, monkeypatch)
    guild_id = 500
    first = economy_db.add_shop_item(guild_id, name="Fumo", description="", price=50, is_default=False)
    second = economy_db.add_shop_item(guild_id, name="Fumo", description="", price=99, is_default=False)
    assert first == second
    items = economy_db.get_shop_items(guild_id)
    assert len([it for it in items if it["name"] == "Fumo"]) == 1


