def test_rename_default_item_does_not_resurrect_original(tmp_path, monkeypatch):
    economy_db = _fresh_economy_db(tmp_path, monkeypatch)
    guild_id = 504
    economy_db.add_shop_item(guild_id, name="🎆 Fireworks", description="Reveal", price=100, is_default=True)
    assert economy_db.update_shop_item_by_name(guild_id, "🎆 Fireworks", name="💥 Booms") is True
    names = [it["name"] for it in economy_db.get_shop_items(guild_id)]
    assert names == ["💥 Booms"]

    cog = economy_cog.Economy(bot=MagicMock())
    asyncio.run(cog._ensure_default_items(SimpleNamespace(id=guild_id)))
    names = [it["name"] for it in economy_db.get_shop_items(guild_id)]
    assert "🎆 Fireworks" not in names
    assert "💥 Booms" in names


