# Database separation: bot.db -> economy.db migration tests
# ------------------------------------------------------------------ #


def _make_source_bot_db(tmp_path):
    """Create a temp bot.db with economy tables + data plus one non-economy table."""
    import sqlite3
    src_path = tmp_path / "bot.db"
    conn = sqlite3.connect(str(src_path))
    conn.executescript(
        """
        CREATE TABLE economy_shop_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            guild_id INTEGER NOT NULL,
            name TEXT NOT NULL,
            description TEXT,
            price INTEGER NOT NULL,
            is_default INTEGER NOT NULL DEFAULT 0
        );
        CREATE TABLE economy_removed_default_items (
            guild_id INTEGER NOT NULL,
            name TEXT NOT NULL,
            PRIMARY KEY (guild_id, name)
        );
        CREATE TABLE economy_accounts (
            guild_id INTEGER NOT NULL,
            user_id INTEGER NOT NULL,
            wallet INTEGER NOT NULL DEFAULT 0,
            bank INTEGER NOT NULL DEFAULT 0,
            last_collect_at TEXT,
            PRIMARY KEY (guild_id, user_id)
        );
        CREATE TABLE economy_inventory (
            guild_id INTEGER NOT NULL,
            user_id INTEGER NOT NULL,
            item_id INTEGER NOT NULL,
            quantity INTEGER NOT NULL DEFAULT 0,
            PRIMARY KEY (guild_id, user_id, item_id),
            FOREIGN KEY (item_id) REFERENCES economy_shop_items(id) ON DELETE CASCADE
        );
        CREATE TABLE economy_channel_balance (
            guild_id INTEGER NOT NULL,
            channel_id INTEGER NOT NULL,
            balance INTEGER NOT NULL DEFAULT 0,
            PRIMARY KEY (guild_id, channel_id)
        );
        CREATE TABLE economy_channel_inventory (
            guild_id INTEGER NOT NULL,
            channel_id INTEGER NOT NULL,
            item_id INTEGER NOT NULL,
            quantity INTEGER NOT NULL DEFAULT 0,
            PRIMARY KEY (guild_id, channel_id, item_id),
            FOREIGN KEY (item_id) REFERENCES economy_shop_items(id) ON DELETE CASCADE
        );
        CREATE TABLE non_economy_table (
            id INTEGER PRIMARY KEY,
            note TEXT
        );
        INSERT INTO economy_shop_items (id, guild_id, name, description, price, is_default) VALUES
            (101, 1, 'Fumo', 'c', 50, 0),
            (102, 1, 'Bomb', 'b', 500, 1);
        INSERT INTO economy_removed_default_items (guild_id, name) VALUES (1, 'Old Boom');
        INSERT INTO economy_accounts (guild_id, user_id, wallet, bank, last_collect_at) VALUES
            (1, 10, 5, 6, '2024-01-01T00:00:00'),
            (1, 11, 7, 8, NULL);
        INSERT INTO economy_inventory (guild_id, user_id, item_id, quantity) VALUES
            (1, 10, 101, 3),
            (1, 10, 999, 9);
        INSERT INTO economy_channel_balance (guild_id, channel_id, balance) VALUES (1, 20, 42);
        INSERT INTO economy_channel_inventory (guild_id, channel_id, item_id, quantity) VALUES
            (1, 20, 102, 4),
            (1, 20, 999, 7);
        INSERT INTO non_economy_table (id, note) VALUES (1, 'keep me');
        """
    )
    conn.commit()
    conn.close()
    return src_path


def _point_at_source_bot_db(tmp_path, monkeypatch):
    """Patch bot_db (migration source) and economy_db (destination) to temp files."""
    import utils.bot_db as bot_db
    import utils.economy_db as economy_db
    src = _make_source_bot_db(tmp_path)
    monkeypatch.setattr(bot_db, "DB_DIR", str(tmp_path))
    monkeypatch.setattr(bot_db, "DB_PATH", str(src))
    monkeypatch.setattr(economy_db, "DB_DIR", str(tmp_path))
    monkeypatch.setattr(economy_db, "DB_PATH", str(tmp_path / "economy.db"))
    monkeypatch.setattr(economy_db, "_DB_READY", False)
    monkeypatch.setattr(economy_db, "_BOT_DB_MIGRATED", False)
    return src


def test_migration_copies_economy_tables_with_ids(tmp_path, monkeypatch):
    import sqlite3
    import utils.economy_db as economy_db
    src = _point_at_source_bot_db(tmp_path, monkeypatch)

    assert [it["id"] for it in economy_db.get_shop_items(1)] == [101, 102]
    assert economy_db.get_removed_default_items(1) == {"Old Boom"}
    assert economy_db.get_economy_account(1, 10) == (5, 6)
    assert economy_db.get_economy_account(1, 11) == (7, 8)
    assert [(i["item_id"], i["quantity"]) for i in economy_db.get_inventory(1, 10)] == [(101, 3)]
    assert economy_db.get_economy_channel_balance(1, 20) == 42
    assert [(i["item_id"], i["quantity"]) for i in economy_db.get_inventory_channel(1, 20)] == [(102, 4)]

    # Orphaned inventory rows (item_id 999 not in shop_items) are skipped.
    assert all(i["item_id"] != 999 for i in economy_db.get_inventory(1, 10))
    assert all(i["item_id"] != 999 for i in economy_db.get_inventory_channel(1, 20))

    conn = sqlite3.connect(str(src))
    conn.row_factory = sqlite3.Row
    assert conn.execute("SELECT COUNT(*) c FROM economy_shop_items").fetchone()["c"] == 2
    assert conn.execute("SELECT COUNT(*) c FROM non_economy_table").fetchone()["c"] == 1
    assert conn.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='economy_accounts'").fetchone() is not None
    conn.close()

    assert economy_db._get_migration_marker() == "1"


def test_migration_is_idempotent(tmp_path, monkeypatch):
    import utils.economy_db as economy_db
    src = _point_at_source_bot_db(tmp_path, monkeypatch)

    economy_db.get_shop_items(1)
    # Simulate restart: clear in-memory flags, then run the migration again.
    monkeypatch.setattr(economy_db, "_DB_READY", False)
    monkeypatch.setattr(economy_db, "_BOT_DB_MIGRATED", False)
    economy_db.get_shop_items(1)
    # Force a direct re-run even with the marker present; nothing duplicates.
    economy_db._migrate_from_bot_db()
    assert len(economy_db.get_shop_items(1)) == 2
    assert economy_db.get_economy_account(1, 10) == (5, 6)
    assert economy_db.get_economy_channel_balance(1, 20) == 42
