def test_post_migration_writes_go_to_economy_db(tmp_path, monkeypatch):
    import sqlite3
    import utils.economy_db as economy_db
    src = _point_at_source_bot_db(tmp_path, monkeypatch)

    economy_db.get_shop_items(1)
    economy_db.add_shop_item(1, "New Item", "", 100, is_default=False)
    economy_db.set_economy_channel_balance(1, 30, 77)

    assert "New Item" in [it["name"] for it in economy_db.get_shop_items(1)]
    assert economy_db.get_economy_channel_balance(1, 30) == 77

    conn = sqlite3.connect(str(src))
    conn.row_factory = sqlite3.Row
    names = [r["name"] for r in conn.execute("SELECT name FROM economy_shop_items").fetchall()]
    balances = [r["balance"] for r in conn.execute("SELECT balance FROM economy_channel_balance").fetchall()]
    conn.close()
    assert "New Item" not in names
    assert 77 not in balances


