def _build_world(gid):
    """Rolechat economy world: categories, roles, members, guild data, cog."""
    guild = _Guild(gid)
    rc = guild.cat("ROLES")
    alt = guild.cat("ALT")
    dead = guild.cat("DEAD")
    houses = guild.cat("HOUSES")
    alive = guild.role("Alive")
    sponsor = guild.role("Sponsor")
    overseer = guild.role("Overseer")
    me = _User(1, "Alice", roles=[alive])
    bob = _User(2, "Bob", roles=[alive])
    rc_alice = guild.ch(101, "alice-rc", category=rc, members=[me])
    rc_bob = guild.ch(102, "bob-rc", category=rc, members=[bob])
    house1 = guild.ch(201, "house-1", category=houses, members=[me, bob])
    guild.members = [me, bob]
    alive.members = [me, bob]
    _setup_guild_data(gid)
    cog = economy_cog.Economy(bot=SimpleNamespace())
    return guild, rc, houses, alive, me, bob, rc_alice, rc_bob, house1, cog


