def test_admin_commands_have_permission_checks():
    for name in ("additem", "edititem", "delitem", "additemrole", "removeitem",
                 "reset_economy", "clear_inventory", "addmoney", "removemoney",
                 "add_money_role", "setcollect", "collect", "leaderboard"):
        assert len(getattr(economy_cog.Economy, name).checks) > 0, name


def test_player_commands_have_no_permission_checks():
    for name in ("use_item", "buy", "inventory", "sell_item", "give_money",
                 "give", "balance", "shop"):
        assert len(getattr(economy_cog.Economy, name).checks) == 0, name


